package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.Binding;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * SPARQL 1.2 native differential corpus (M6): triple-term data plus directional language-tag matrices, evaluated with
 * the native engine on and off — the TripleRef scan, the TRIPLE decode kind, the 1.2 value functions (LANGDIR, hasLANG,
 * hasLANGDIR, STRLANGDIR, TRIPLE/SUBJECT/PREDICATE/OBJECT, isTRIPLE) and triple-term value equality (numeric-collapse
 * recursion, W3C eval-triple-terms/op-2 family) must all agree with the generic evaluator.
 */
@Timeout(value = 120, unit = TimeUnit.SECONDS)
public class LmdbNativeSparql12DifferentialTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String PREFIX = "PREFIX ex: <" + EX + ">\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI says = vf.createIRI(EX, "says");
			IRI claims = vf.createIRI(EX, "claims");
			IRI label = vf.createIRI(EX, "label");
			IRI age = vf.createIRI(EX, "age");
			IRI alice = vf.createIRI(EX, "alice");
			IRI bob = vf.createIRI(EX, "bob");

			// triple terms differing only in numeric lexical form (value-equal, term-distinct): op-2 family
			TripleTerm t1 = vf.createTripleTerm(alice, age, vf.createLiteral("42", XSD.INTEGER));
			TripleTerm t2 = vf.createTripleTerm(alice, age, vf.createLiteral("42.0", XSD.DECIMAL));
			TripleTerm t3 = vf.createTripleTerm(bob, age, vf.createLiteral("42", XSD.INTEGER));
			TripleTerm nested = vf.createTripleTerm(alice, claims, t1);
			conn.add(alice, says, t1);
			conn.add(alice, says, t2);
			conn.add(bob, says, t3);
			conn.add(bob, claims, nested);
			conn.add(alice, age, vf.createLiteral("42", XSD.INTEGER));

			// directional language-tag matrix
			conn.add(alice, label, vf.createLiteral("alice", "en"));
			conn.add(alice, label, vf.createLiteral("alice", "en", Literal.BaseDirection.LTR));
			conn.add(alice, label, vf.createLiteral("alice", "en", Literal.BaseDirection.RTL));
			conn.add(bob, label, vf.createLiteral("bob"));
			conn.add(bob, label, vf.createLiteral("بوب", "ar", Literal.BaseDirection.RTL));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> result = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			List<String> canonical = new ArrayList<>(result.size());
			for (BindingSet bs : result) {
				TreeMap<String, String> sorted = new TreeMap<>();
				for (Binding binding : bs) {
					sorted.put(binding.getName(), binding.getValue().toString());
				}
				canonical.add(sorted.toString());
			}
			return canonical;
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void assertSameRows(String query) {
		List<String> generic = rows(query, false);
		assertThat(rows(query, true))
				.as("native vs generic rows for:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	private void assertSameRowsNonEmpty(String query) {
		List<String> generic = rows(query, false);
		assertThat(generic).as("generic oracle must produce rows:\n%s", query).isNotEmpty();
		assertThat(rows(query, true))
				.as("native vs generic rows for:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	// ---------------------------------------------------------------- TripleRef scan

	@Test
	public void tripleTermPatternsScanNatively() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?x ex:says <<( ?s ?p ?o )>> }");
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?x ex:says <<( ex:alice ?p ?o )>> }");
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?x ex:says <<( ?s ex:age 42 )>> }");
		assertSameRows(PREFIX + "SELECT * WHERE { ?x ex:says <<( ?s ex:doesNotExist ?o )>> }");
		// nested triple terms: the object of the outer term is itself a triple term
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?x ex:claims <<( ?s ex:claims ?inner )>> }");
	}

	@Test
	public void tripleTermJoinAcrossPatterns() {
		// the triple-term variable joins two occurrences by term identity
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?y WHERE { ?x ex:says ?t . ?y ex:says ?t . FILTER(?x != ?y) }");
		// component join back into ordinary statements
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT * WHERE { ?x ex:says <<( ?s ?p ?o )>> . ?s ?p ?o . }");
	}

	// ---------------------------------------------------------------- 1.2 value functions

	@Test
	public void tripleTermFunctions() {
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?t WHERE { ?x ex:says ?t . FILTER(isTRIPLE(?t)) }");
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x ?s ?p ?o WHERE { ?x ex:says ?t . BIND(SUBJECT(?t) AS ?s) BIND(PREDICATE(?t) AS ?p) "
				+ "BIND(OBJECT(?t) AS ?o) }");
		// TRIPLE() constructor: rebuilt terms must be sameTerm-equal to the stored ones
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x WHERE { ?x ex:says ?t . BIND(TRIPLE(SUBJECT(?t), PREDICATE(?t), OBJECT(?t)) AS ?u) "
				+ "FILTER(sameTerm(?t, ?u)) }");
		// component functions on non-triples are type errors
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?s WHERE { ?x ex:label ?l . BIND(SUBJECT(?l) AS ?s) }");
	}

	@Test
	public void tripleTermValueEquality() {
		// value equality with numeric collapse: <<( :alice :age 42 )>> = <<( :alice :age 42.0 )>> is TRUE while
		// sameTerm is FALSE (the op-2 family)
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?a ?b WHERE { ex:alice ex:says ?a . ex:alice ex:says ?b . "
				+ "FILTER(!sameTerm(?a, ?b)) FILTER(?a = ?b) }");
		assertSameRows(PREFIX
				+ "SELECT ?a ?b WHERE { ?x ex:says ?a . ?y ex:says ?b . FILTER(?a != ?b) }");
		// triple term IN a candidate list mixing types (per-candidate error boundaries)
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?t WHERE { ?x ex:says ?t . FILTER(?t IN (\"o\", <<( ex:alice ex:age 42.0 )>>)) }");
	}

	@Test
	public void tripleTermConstructorExpression() {
		// the <<( ... )>> expression form with constants and variables
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x WHERE { ?x ex:says ?t . FILTER(?t = <<( ex:alice ex:age 42 )>>) }");
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x ?o WHERE { ?x ex:age ?o . BIND(<<( ?x ex:age ?o )>> AS ?t) "
				+ "?who ex:says ?t . }");
	}

	// ---------------------------------------------------------------- dir-lang functions

	@Test
	public void langDirFamily() {
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?d WHERE { ?x ex:label ?l . BIND(LANGDIR(?l) AS ?d) }");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?l WHERE { ?x ex:label ?l . FILTER(hasLANG(?l)) }");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?l WHERE { ?x ex:label ?l . FILTER(hasLANGDIR(?l)) }");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x ?l WHERE { ?x ex:label ?l . FILTER(!hasLANGDIR(?l)) }");
		// hasLANG/hasLANGDIR are plain false on non-literals, never errors
		assertSameRowsNonEmpty(PREFIX + "SELECT ?x WHERE { ?x ex:says ?t . FILTER(!hasLANG(?t)) }");
	}

	@Test
	public void strLangDirConstructsDirectionalLiterals() {
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x ?d WHERE { ?x ex:label ?l . FILTER(!hasLANG(?l)) "
				+ "BIND(STRLANGDIR(STR(?l), \"en\", \"ltr\") AS ?d) }");
		// constructed dir-lang literal joins a stored one by term identity
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?x WHERE { BIND(STRLANGDIR(\"alice\", \"en\", \"rtl\") AS ?d) ?x ex:label ?d . }");
		// invalid direction and empty language are type errors
		assertSameRows(PREFIX + "SELECT ?d WHERE { BIND(STRLANGDIR(\"a\", \"en\", \"sideways\") AS ?d) }");
		assertSameRows(PREFIX + "SELECT ?d WHERE { BIND(STRLANGDIR(\"a\", \"\", \"ltr\") AS ?d) }");
	}

	@Test
	public void directionalLiteralsGroupByDistinctly() {
		// the three "alice"@en variants (no dir, ltr, rtl) are distinct terms in GROUP BY and COUNT(DISTINCT)
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT (COUNT(DISTINCT ?l) AS ?n) WHERE { ex:alice ex:label ?l }");
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT ?l (COUNT(*) AS ?n) WHERE { ?x ex:label ?l } GROUP BY ?l");
	}

	@Test
	public void tripleRefKillSwitchRestoresIslandRoute() {
		String query = PREFIX + "SELECT * WHERE { ?x ex:says <<( ?s ?p ?o )>> }";
		List<String> withNative = rows(query, true);
		String previous = System.getProperty("rdf4j.lmdb.nativeTripleTerms.enabled");
		System.setProperty("rdf4j.lmdb.nativeTripleTerms.enabled", "false");
		try {
			assertThat(rows(query, true)).containsExactlyInAnyOrderElementsOf(withNative);
		} finally {
			if (previous == null) {
				System.clearProperty("rdf4j.lmdb.nativeTripleTerms.enabled");
			} else {
				System.setProperty("rdf4j.lmdb.nativeTripleTerms.enabled", previous);
			}
		}
	}
}
